import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import toast from 'react-hot-toast';
import logoDark from '../assets/logo-lhm-dark.png';

export default function LoginPage() {
  const { login } = useAuth();
  const navigate  = useNavigate();
  const [form, setForm]     = useState({ email: '', password: '' });
  const [loading, setLoading] = useState(false);
  const [error, setError]   = useState('');

  const handleSubmit = async e => {
    e.preventDefault();
    setLoading(true); setError('');
    try {
      await login(form.email, form.password);
      toast.success('Bienvenue !');
      navigate('/');
    } catch (err) {
      setError(err.response?.data?.message || 'Identifiants incorrects');
    } finally {
      setLoading(false);
    }
  };

  const demos = [
    { label: 'Admin',      email: 'admin@lhm-madagascar.org',       pwd: 'Admin@1234' },
    { label: 'Direction',  email: 'direction@lhm-madagascar.org',   pwd: 'Direction@1234' },
    { label: 'RH',         email: 'rh@lhm-madagascar.org',          pwd: 'RH@1234' },
    { label: 'Stock',      email: 'stock@lhm-madagascar.org',       pwd: 'Stock@1234' },
    { label: 'Volontaires',email: 'volontaires@lhm-madagascar.org', pwd: 'Vol@1234' },
  ];

  return (
    <div style={{ minHeight: '100vh', display: 'flex', background: 'linear-gradient(135deg,#091628 0%,#0f2044 50%,#1a3560 100%)' }}>
      {/* Panel gauche */}
      <div style={{ flex: 1, minWidth: 260, display: 'flex', alignItems: 'center', justifyContent: 'center', flexDirection: 'column', padding: '40px 32px', color: 'white' }}>
        <div style={{ maxWidth: 400, width: '100%' }}>
          <img src={logoDark} alt="LHM Madagascar" style={{ maxWidth: 260, width: '100%', objectFit: 'contain', filter: 'brightness(10)', marginBottom: 32 }} />
          <h2 style={{ fontFamily: "'Playfair Display',serif", fontSize: '1.8rem', fontWeight: 700, marginBottom: 12 }}>
            Système de Gestion
          </h2>
          <p style={{ opacity: .75, lineHeight: 1.6, fontSize: '0.95rem', marginBottom: 24 }}>
            Plateforme intégrée pour la gestion du personnel, des ressources, des projets et du programme BCC de LHM Madagascar.
          </p>
          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
            {['Personnel','Stock','Projets','BCC','Volontaires'].map(m => (
              <span key={m} style={{ background: 'rgba(201,168,76,0.2)', border: '1px solid rgba(201,168,76,0.4)', color: '#e0c06e', padding: '4px 12px', borderRadius: 20, fontSize: '0.78rem', fontWeight: 600 }}>{m}</span>
            ))}
          </div>
        </div>
      </div>

      {/* Panel droite — formulaire */}
      <div style={{ flex: 1, minWidth: 280, maxWidth: 480, background: 'white', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '40px 32px' }}>
        <div style={{ width: '100%', maxWidth: 380 }}>
          <h1 style={{ fontFamily: "'Playfair Display',serif", fontSize: '1.6rem', color: '#0f2044', marginBottom: 6 }}>Connexion</h1>
          <p style={{ color: '#6b7280', fontSize: '0.88rem', marginBottom: 28 }}>Entrez vos identifiants pour accéder au système</p>

          {error && (
            <div style={{ background: '#fee2e2', border: '1px solid #fca5a5', color: '#991b1b', padding: '10px 14px', borderRadius: 8, fontSize: '0.85rem', marginBottom: 16 }}>
              ⚠️ {error}
            </div>
          )}

          <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
            <div>
              <label>Email</label>
              <input type="email" value={form.email} onChange={e => setForm({...form, email: e.target.value})} placeholder="votre@email.org" required autoFocus />
            </div>
            <div>
              <label>Mot de passe</label>
              <input type="password" value={form.password} onChange={e => setForm({...form, password: e.target.value})} placeholder="••••••••" required />
            </div>
            <button type="submit" disabled={loading}
              style={{ background: loading ? '#9ca3af' : '#0f2044', color: 'white', padding: '12px', borderRadius: 10, fontWeight: 700, fontSize: '0.95rem', cursor: loading ? 'not-allowed' : 'pointer', marginTop: 4, transition: 'all 0.2s' }}>
              {loading ? '⏳ Connexion...' : '🔐 Se connecter'}
            </button>
          </form>

          {/* Comptes de démo */}
          <div style={{ marginTop: 24, borderTop: '1px solid #e5e7eb', paddingTop: 16 }}>
            <p style={{ fontSize: '0.72rem', color: '#9ca3af', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: 10, fontWeight: 600 }}>Comptes de démonstration</p>
            <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
              {demos.map(d => (
                <button key={d.label} type="button"
                  onClick={() => setForm({ email: d.email, password: d.pwd })}
                  style={{ background: '#f3f4f6', color: '#374151', border: '1px solid #e5e7eb', padding: '4px 10px', borderRadius: 6, fontSize: '0.75rem', fontWeight: 600, cursor: 'pointer' }}>
                  {d.label}
                </button>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
